CREATE CATALOG IF NOT EXISTS retail_dev COMMENT 'Orders, customers and payments for a retail business, modelled as bronze, silver and gold.';
CREATE SCHEMA IF NOT EXISTS retail_dev.landing COMMENT 'Landing zone: source files as delivered';
CREATE SCHEMA IF NOT EXISTS retail_dev.bronze COMMENT 'Raw, append-only copies of source data as text';
CREATE SCHEMA IF NOT EXISTS retail_dev.silver COMMENT 'Typed, validated, deduplicated current state';
CREATE SCHEMA IF NOT EXISTS retail_dev.gold COMMENT 'Curated aggregates for consumption';
CREATE SCHEMA IF NOT EXISTS retail_dev.governance COMMENT 'Mask functions and other governance objects';
CREATE VOLUME IF NOT EXISTS retail_dev.landing.raw COMMENT 'Landing files by source: one folder per source table';

-- Column masks. Bind them in the pipeline SQL; they must exist first.
CREATE OR REPLACE FUNCTION retail_dev.governance.mask_email(v STRING)
RETURNS STRING
COMMENT 'Column mask (email): readers in the privileged and runner groups see the real value'
RETURN CASE
  WHEN v IS NULL THEN NULL
  WHEN is_account_group_member('lakehouse_pii_readers') OR is_account_group_member('lakehouse_pipeline_runners') THEN v
  ELSE concat('***@', substring_index(v, '@', -1))
END;

CREATE OR REPLACE FUNCTION retail_dev.governance.mask_redact(v STRING)
RETURNS STRING
COMMENT 'Column mask (redact): readers in the privileged and runner groups see the real value'
RETURN CASE
  WHEN v IS NULL THEN NULL
  WHEN is_account_group_member('lakehouse_pii_readers') OR is_account_group_member('lakehouse_pipeline_runners') THEN v
  ELSE '[REDACTED]'
END;

